package com.bank.settlement.service;

import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.List;

@Service
@RequiredArgsConstructor
@Slf4j
public class SettlementService {

    private final TradeRepository tradeRepo;

    @Transactional
    public int settlePendingTrades() {
        List<Trade> pending = tradeRepo.findByStatus("PENDING");
        log.info("Found {} pending trades to settle", pending.size());
        pending.forEach(trade -> {
            trade.settle();
            tradeRepo.save(trade);
            log.info("Settled: {} {} x{} @ Rs.{}", trade.getTradeId(),
                trade.getSymbol(), trade.getQuantity(), trade.getPrice());
        });
        return pending.size();
    }
}
```

