// CommandLineRunner: runs AFTER context is ready, BEFORE serving traffic
package com.bank.settlement.runner;

import com.bank.settlement.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.boot.CommandLineRunner;
import org.springframework.stereotype.Component;

@Component
@RequiredArgsConstructor
@Slf4j
public class StartupDataLoader implements CommandLineRunner {

    private final TradeRepository tradeRepo;

    @Override
    public void run(String... args) {
        long count = tradeRepo.count();
        log.info("[STARTUP] CommandLineRunner: {} trades in database", count);
        log.info("[STARTUP] Database connectivity verified — ready to serve");
    }
}
```

