package com.bank.settlement.service;

import com.bank.settlement.model.Trade;
import com.bank.settlement.repository.TradeRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.*;
import org.mockito.junit.jupiter.MockitoExtension;
import java.util.List;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class SettlementServiceTest {

    @Mock TradeRepository tradeRepo;
    @InjectMocks SettlementService settlementService;

    @Test
    void shouldSettleAllPendingTrades() {
        Trade trade = mock(Trade.class);
        when(tradeRepo.findByStatus("PENDING")).thenReturn(List.of(trade));

        int count = settlementService.settlePendingTrades();

        assertThat(count).isEqualTo(1);
        verify(trade).settle();
        verify(tradeRepo).save(trade);
    }
}
